# Code generated by Claude
"""
Find a realistic arm motion that shows the solver's elbow snap WITH physics, and film it.

    source .venv/bin/activate
    python experiments/realistic_snap.py                 # check every candidate, render the first pass
    python experiments/realistic_snap.py --no-render     # just the table
    python experiments/realistic_snap.py --only b1       # one candidate

Candidates (left arm; the right arm is the mirror image). Each is a smooth 4 s move of
the arm (elbow bent 90 deg -> joint 4 = 0), then a 2 s hold, 750 Hz:
  a  lowering to rest: joints 1-3 = 0, hand in front of the body -> arm hanging straight
     (three wrist settings: zero, wristA, wristB)
  b  the poses of experiments/elbow_snap_sweep.py (forward at shoulder height, down to the
     side, reaching up, across the body), each with wristA and wristB. Joints 1-3 and the
     wrist are the sweep's; only joint 4 moves.

Checks, per candidate, before anything is rendered:
  hold    PD (750 Hz, torque limits, gravcomp = 1 on link1..fingers of both arms, base
          stationary) holds the start pose and the end pose for 2 s; passes when the hand
          sags less than 5 mm at both. The end pose is the safety filter's output.
  snap    the motion goes through the safety filter (ON) without physics; passes when a
          joint jumps more than 0.5 rad in one step or the hand (tcp) is more than 20 mm
          from the commanded hand right after a jump.
  motion  commanded and filtered motion are within the joint limits and free of
          self-collision (branch_jump_demo.motion_check).
The video (data/branch_jump/realistic_snap.mp4 plus realistic_before.png / realistic_after.png)
is rendered for the first candidate that passes all three; nothing is rendered if none does.
"""

import argparse
import contextlib
import io
import os
import sys
from pathlib import Path

if "--no-render" not in sys.argv:        # offscreen rendering needs no display
    os.environ.setdefault("MUJOCO_GL", "egl")

import numpy as np

PROJECT_ROOT = Path(__file__).resolve().parent.parent
sys.path.insert(0, str(PROJECT_ROOT))

from experiments.branch_jump_demo import (RATE_HZ, find_jumps, hold_check, load_model,  # noqa: E402
                                          motion_check, render_video, run_trajectory)
from experiments.elbow_snap_sweep import POSES, WRIST_VARIANTS, joints_for_direction  # noqa: E402
from models.policies.branch_jump_policy import SOLVER_DEFAULT_Q, BranchJumpPolicy  # noqa: E402
from src.safety_filter import SafetyFilter  # noqa: E402

DURATION, HOLD = 4.0, 2.0
SAG_LIMIT_MM, JUMP_RAD, HAND_ERR_MM, JUMP_THRESHOLD = 5.0, 0.5, 20.0, 0.1
ELBOW_BENT = float(SOLVER_DEFAULT_Q[3])                      # 90 degrees
B_POSES = ("forward at shoulder height", "down to the side", "reaching up", "across the body")
np.set_printoptions(precision=3, suppress=True, linewidth=140)


def build_candidates(arm):
    import openarm_teleop
    spec = np.load(Path(openarm_teleop.__file__).parent / "assets/specs/openarm_v1.npz")
    limits = (spec[f"{arm}_arm/joint_lower"], spec[f"{arm}_arm/joint_upper"])
    sf = SafetyFilter(collision_avoidance=True)
    cands = []
    for wname in ("base", "wristA", "wristB"):                 # a: lowering to rest
        w = WRIST_VARIANTS[wname]
        cands.append(dict(id=f"a/{wname}", name=f"lowering to rest, wrist {wname}",
                          end=np.array([0, 0, 0, 0, *w], float),
                          start=np.array([0, 0, 0, ELBOW_BENT, *w], float)))
    poses = {p[0]: p[1] for p in POSES}
    for i, pname in enumerate(B_POSES, 1):                     # b: the sweep's poses
        j1, j2, j3, err = joints_for_direction(sf, arm, poses[pname], limits)
        for wname in ("wristA", "wristB"):
            end = np.array([j1, j2, j3, 0.0, *WRIST_VARIANTS[wname]])
            start = end.copy()
            start[3] = ELBOW_BENT
            cands.append(dict(id=f"b{i}/{wname}", name=f"{pname}, wrist {wname}", end=end,
                              start=start, dir_err=err))
    return cands


def hand_positions(m, d, arm, traj):
    """Hand (tcp) world position for every row of a joint trajectory (base fixed)."""
    import mujoco
    qadr = [m.jnt_qposadr[m.actuator_trnid[mujoco.mj_name2id(
        m, mujoco.mjtObj.mjOBJ_ACTUATOR, f"{arm}_joint{i}_ctrl"), 0]] for i in range(1, 8)]
    tcp = m.body(f"openarm_{arm}_hand_tcp").id
    out = np.zeros((len(traj), 3))
    for k, q in enumerate(traj):
        d.qpos[qadr] = q
        mujoco.mj_kinematics(m, d)
        out[k] = d.xpos[tcp]
    return out


def evaluate(c, arm):
    import mujoco
    policy = BranchJumpPolicy(arm, c["end"], start=c["start"], duration=DURATION, profile="smooth")
    t, cmd, out, _ = run_trajectory(policy, "previous", HOLD)
    on = out["on"]
    events = find_jumps(t, on, cmd, JUMP_THRESHOLD)
    m = load_model()
    d = mujoco.MjData(m)
    herr = 1000.0 * np.linalg.norm(hand_positions(m, d, arm, on) - hand_positions(m, d, arm, cmd), axis=1)
    big = max(events, key=lambda e: e["size"], default=None)
    r = dict(policy=policy, t=t, cmd=cmd, on=on, events=events, big=big, hand_err=herr,
             hand_err_max=float(herr.max()), hand_err_end=float(herr[-1]))
    if big is not None:
        k = big["step"]
        r.update(jump=big["size"], jump_t=big["t"], jump_elbow_deg=float(np.degrees(cmd[k, 3])),
                 jump_joints=", ".join(f"j{j} {big['delta'][j - 1]:+.2f}" for j in big["joints"]),
                 hand_err_snap=float(herr[k]))
    else:
        r.update(jump=0.0, jump_t=None, jump_elbow_deg=None, jump_joints="", hand_err_snap=0.0)
    r["snap_ok"] = bool(big is not None and (r["jump"] > JUMP_RAD or r["hand_err_snap"] > HAND_ERR_MM))
    buf = io.StringIO()                                       # motion_check is chatty: keep its text
    with contextlib.redirect_stdout(buf):
        r["motion_ok"] = bool(motion_check(policy, cmd, on))
    r["motion_text"] = buf.getvalue()
    sag = hold_check(policy, [("start pose", on[0], cmd[0]), ("end pose", on[-1], cmd[-1])],
                     verbose=False)
    r["sag_start"], r["sag_end"] = sag[0]["final_mm"], sag[1]["final_mm"]
    r["sag_peak"] = max(s["max_mm"] for s in sag)
    r["hold_ok"] = bool(max(r["sag_start"], r["sag_end"]) < SAG_LIMIT_MM)
    r["all_ok"] = r["hold_ok"] and r["snap_ok"] and r["motion_ok"]
    return r


def table(cands, results):
    head = (f"{'id':10s} {'candidate':44s} {'sag start':>9s} {'sag end':>8s} {'hold':>5s} | "
            f"{'jump rad':>8s} {'at t':>6s} {'elbow':>6s} {'hand err':>8s} {'snap':>5s} | {'motion':>6s} {'RESULT':>6s}")
    lines = [head, "-" * len(head)]
    for c in cands:
        r = results.get(c["id"])
        if r is None:
            continue
        lines.append(
            f"{c['id']:10s} {c['name']:44s} {r['sag_start']:7.1f}mm {r['sag_end']:6.1f}mm "
            f"{'pass' if r['hold_ok'] else 'FAIL':>5s} | {r['jump']:8.2f} "
            f"{('%.2fs' % r['jump_t']) if r['jump_t'] is not None else '-':>6s} "
            f"{('%.1f°' % r['jump_elbow_deg']) if r['jump_elbow_deg'] is not None else '-':>6s} "
            f"{r['hand_err_snap']:6.0f}mm {'pass' if r['snap_ok'] else 'FAIL':>5s} | "
            f"{'ok' if r['motion_ok'] else 'FAIL':>6s} {'PASS' if r['all_ok'] else 'fail':>6s}")
    return "\n".join(lines)


def main():
    ap = argparse.ArgumentParser(description=__doc__.split("\n\n")[0])
    ap.add_argument("--arm", choices=("left", "right"), default="left")
    ap.add_argument("--only", help="candidate id (e.g. b1/wristB)")
    ap.add_argument("--no-render", action="store_true", help="only the table")
    ap.add_argument("--out", default="data/branch_jump")
    args = ap.parse_args()
    cands = [c for c in build_candidates(args.arm) if not args.only or c["id"].startswith(args.only)]
    results = {}
    for c in cands:
        print(f"... {c['id']}: {c['name']}", flush=True)
        results[c["id"]] = evaluate(c, args.arm)
        if not results[c["id"]]["motion_ok"]:
            print(results[c["id"]]["motion_text"])
    txt = table(cands, results)
    out_dir = PROJECT_ROOT / args.out
    out_dir.mkdir(parents=True, exist_ok=True)
    (out_dir / "realistic_candidates.txt").write_text(
        f"{args.arm} arm; sag limit {SAG_LIMIT_MM:g} mm; snap = jump > {JUMP_RAD:g} rad or hand error "
        f"> {HAND_ERR_MM:g} mm; hold {HOLD:g} s\n{txt}\n")
    print(f"\n{txt}\n\nHand error at the snap = distance between the commanded hand and the filtered "
          f"output's hand right after the largest jump. Sag = hand vs where the tracked joints put it.")
    winner = next((c for c in cands if results[c["id"]]["all_ok"]), None)
    if winner is None:
        print("\nNo candidate passes all checks: nothing rendered.")
        sys.exit(2)
    r = results[winner["id"]]
    print(f"\nFirst candidate that passes: {winner['id']} ({winner['name']})")
    if args.no_render:
        return
    mp4 = out_dir / "realistic_snap.mp4"
    info = render_video(mp4, r["t"], r["cmd"], r["on"], r["policy"], r["events"], rich=True,
                        still_dir=out_dir, still_prefix="realistic")
    e = r["big"]
    print(f"Saved {mp4}\nStills: {out_dir / 'realistic_before.png'}, {out_dir / 'realistic_after.png'}\n"
          f"Snap at t = {e['t']:.4f} s, commanded elbow {r['jump_elbow_deg']:.2f} deg; joint jumps "
          + ", ".join(f"j{j} {e['delta'][j - 1]:+.3f} rad" for j in range(1, 8) if abs(e['delta'][j - 1]) > 0.005)
          + f"; hand error {r['hand_err_snap']:.0f} mm right after (max {r['hand_err_max']:.0f} mm); "
          f"video hand gap before/after stills {info['gap_before_mm']:.0f}/{info['gap_after_mm']:.0f} mm")


if __name__ == "__main__":
    main()
